const { Client, SlashCommandBuilder } = require('discord.js');

// Create a new Discord client 
const client = new Client({ intents: ['GUILDS', 'GUILD_MESSAGES'] });

// Define the /ban slash command
const banCommand = new SlashCommandBuilder()
  .setName('ban')
  .setDescription('Ban a member from the server.');

// Register the /ban slash command
client.commands.set('ban', banCommand);

// Listen for the interactionCreate event (i.e. when a slash command is invoked)
client.on('interactionCreate', async interaction => {
  if (interaction.isCommand()) {
    // Check if the command is /ban
    if (interaction.commandName === 'ban') {
      // Confirm that the user has authority to ban the member
      if (!interaction.member.permissions.has('BAN_MEMBERS')) {
        return interaction.reply('You do not have permission to ban members!');
      }

      // Get the member to ban
      const memberToBan = await interaction.guild.members.fetch(interaction.options.getUser('victim'));
      if (!memberToBan) {
        return interaction.reply('Invalid member specified.');
      }

      // Confirm that the member is not a bot account
      if (memberToBan.user.bot) {
        return interaction.reply('Cannot ban a bot account.');
      }

      // Confirm that the member is not the bot owner
      if (memberToBan.user.id === 'BOT_OWNER_ID') {
        return interaction.reply('Cannot ban the bot owner.');
      }

      // Confirm that the member is not the invoking user
      if (memberToBan.user.id === interaction.user.id) {
        return interaction.reply('Cannot ban yourself.');
      }

      // Confirm that the member has not already been banned
      if (memberToBan._roles.includes('BOT_BAN_ROLE_ID')) {
        return interaction.reply('Member is already banned.');
      }

      // Confirm the ban
      await memberToBan.roles.remove('BOT_BAN_ROLE_ID');
      await interaction.reply(`Successfully banned ${memberToBan.user.tag}!`);
    }
  }
});

// Login to Discord with your bot token
client.login('YOUR_BOT_TOKEN');
```
