function checkForPrimes(arr) {
  // Loop through the input array and check if each number is prime
  for (let i = 0; i < arr.length; i++) {
    let num = arr[i];

    // Check if the current number is prime
    if (isPrime(num)) {
      console.log("Found prime number:", num);
      break;
    }
  }
}

// Helper function to check if a number is prime
function isPrime(num) {
  if (num <= 1) {
    return false;
  }
  for (let i = 2; i < num; i++) {
    if (num % i === 0) {
      return false;
    }
  }
  return true;
}

let arr = [5, 7, 11, 13, 17];

checkForPrimes(arr);
```

